//! `app calc`: a 64-bit signed integer expression evaluator (see SPEC.md, section `calc`).
//!
//! Each input line is evaluated independently. The evaluator is an operator-precedence
//! (shunting-yard) parser driven by explicit stacks rather than recursion, so arbitrarily
//! deep nesting such as `((((…))))` or `- - - … 1` cannot overflow the call stack.

use std::io::{self, BufWriter, Read, Write};

/// Entry point for `app calc`: reads standard input, writes standard output.
pub fn run() -> io::Result<()> {
    let mut input = Vec::new();
    io::stdin().lock().read_to_end(&mut input)?;

    let stdout = io::stdout().lock();
    let mut out = BufWriter::new(stdout);
    let mut evaluator = Evaluator::default();

    for line in input.split(|&b| b == b'\n') {
        if line.iter().all(|&b| is_blank(b)) {
            continue;
        }
        match evaluator.eval(line) {
            Ok(value) => writeln!(out, "{value}")?,
            Err(_) => out.write_all(b"error\n")?,
        }
    }
    out.flush()
}

/// Why an expression has no value. All variants print as `error`; the distinction
/// exists for clarity and testing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CalcError {
    Syntax,
    DivisionByZero,
    Overflow,
}

type CalcResult<T> = Result<T, CalcError>;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum BinaryOp {
    Add,
    Sub,
    Mul,
    Div,
    Rem,
}

impl BinaryOp {
    fn from_byte(b: u8) -> Option<Self> {
        Some(match b {
            b'+' => Self::Add,
            b'-' => Self::Sub,
            b'*' => Self::Mul,
            b'/' => Self::Div,
            b'%' => Self::Rem,
            _ => return None,
        })
    }

    fn precedence(self) -> u8 {
        match self {
            Self::Add | Self::Sub => 1,
            Self::Mul | Self::Div | Self::Rem => 2,
        }
    }

    fn apply(self, lhs: i64, rhs: i64) -> CalcResult<i64> {
        match self {
            Self::Add => lhs.checked_add(rhs).ok_or(CalcError::Overflow),
            Self::Sub => lhs.checked_sub(rhs).ok_or(CalcError::Overflow),
            Self::Mul => lhs.checked_mul(rhs).ok_or(CalcError::Overflow),
            Self::Div | Self::Rem if rhs == 0 => Err(CalcError::DivisionByZero),
            // The only remaining failure is i64::MIN / -1.
            Self::Div => lhs.checked_div(rhs).ok_or(CalcError::Overflow),
            // i64::MIN % -1 is mathematically 0, which `wrapping_rem` yields.
            Self::Rem => Ok(lhs.wrapping_rem(rhs)),
        }
    }
}

/// An entry on the operator stack.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StackOp {
    Binary(BinaryOp),
    /// Prefix negation; binds tighter than any binary operator.
    Negate,
    /// An open parenthesis acting as a barrier.
    LParen,
}

/// Reusable evaluator; keeps its stack allocations across lines.
#[derive(Debug, Default)]
pub struct Evaluator {
    values: Vec<i64>,
    ops: Vec<StackOp>,
}

impl Evaluator {
    /// Evaluates one expression (without its line terminator).
    pub fn eval(&mut self, expr: &[u8]) -> CalcResult<i64> {
        self.values.clear();
        self.ops.clear();

        let mut pos = 0;
        // True when the grammar expects an operand (number, `(` or unary `-`) next.
        let mut expect_operand = true;

        while let Some(&b) = expr.get(pos) {
            if is_blank(b) {
                pos += 1;
                continue;
            }

            if expect_operand {
                match b {
                    b'0'..=b'9' => {
                        let (value, len) = parse_number(&expr[pos..])?;
                        self.values.push(value);
                        pos += len;
                        expect_operand = false;
                        continue;
                    }
                    b'-' => self.ops.push(StackOp::Negate),
                    b'(' => self.ops.push(StackOp::LParen),
                    _ => return Err(CalcError::Syntax),
                }
            } else if let Some(op) = BinaryOp::from_byte(b) {
                // Left associativity: reduce everything of equal or higher precedence.
                self.reduce_while(|top| match top {
                    StackOp::Negate => true,
                    StackOp::Binary(prev) => prev.precedence() >= op.precedence(),
                    StackOp::LParen => false,
                })?;
                self.ops.push(StackOp::Binary(op));
                expect_operand = true;
            } else if b == b')' {
                self.reduce_while(|top| top != StackOp::LParen)?;
                if self.ops.pop() != Some(StackOp::LParen) {
                    return Err(CalcError::Syntax);
                }
            } else {
                return Err(CalcError::Syntax);
            }
            pos += 1;
        }

        if expect_operand {
            // Empty input or a dangling operator / `(` / `-`.
            return Err(CalcError::Syntax);
        }
        self.reduce_while(|top| top != StackOp::LParen)?;
        if !self.ops.is_empty() {
            return Err(CalcError::Syntax);
        }
        match self.values[..] {
            [value] => Ok(value),
            _ => unreachable!("a complete expression reduces to exactly one value"),
        }
    }

    /// Pops and applies operators while `pred` holds for the top of the operator stack.
    fn reduce_while(&mut self, pred: impl Fn(StackOp) -> bool) -> CalcResult<()> {
        while let Some(&top) = self.ops.last() {
            if !pred(top) {
                break;
            }
            self.ops.pop();
            self.apply(top)?;
        }
        Ok(())
    }

    fn apply(&mut self, op: StackOp) -> CalcResult<()> {
        // The parser state machine guarantees operands are present whenever an
        // operator is reduced, so a missing value is an internal invariant violation.
        const INVARIANT: &str = "operator reduced without its operands";
        let result = match op {
            StackOp::Negate => {
                let value = self.values.pop().expect(INVARIANT);
                value.checked_neg().ok_or(CalcError::Overflow)?
            }
            StackOp::Binary(op) => {
                let rhs = self.values.pop().expect(INVARIANT);
                let lhs = self.values.pop().expect(INVARIANT);
                op.apply(lhs, rhs)?
            }
            StackOp::LParen => unreachable!("parentheses are never applied"),
        };
        self.values.push(result);
        Ok(())
    }
}

/// Parses the maximal run of ASCII digits at the start of `digits` (which must begin
/// with one). Returns the value and the number of bytes consumed.
fn parse_number(digits: &[u8]) -> CalcResult<(i64, usize)> {
    let len = digits.iter().take_while(|b| b.is_ascii_digit()).count();
    let value = digits[..len].iter().try_fold(0i64, |acc, &d| {
        acc.checked_mul(10)
            .and_then(|acc| acc.checked_add(i64::from(d - b'0')))
            .ok_or(CalcError::Overflow)
    })?;
    Ok((value, len))
}

fn is_blank(b: u8) -> bool {
    b == b' ' || b == b'\t'
}

#[cfg(test)]
mod tests {
    use super::*;

    fn eval(s: &str) -> CalcResult<i64> {
        Evaluator::default().eval(s.as_bytes())
    }

    #[test]
    fn arithmetic_and_precedence() {
        assert_eq!(eval("1 + 2 * 3"), Ok(7));
        assert_eq!(eval("(1 + 2) * 3"), Ok(9));
        assert_eq!(eval("1 + 2 * 3 - 4 / 2 % 3"), Ok(5));
        assert_eq!(eval("10 - 4 - 3"), Ok(3));
        assert_eq!(eval("100 / 10 / 5"), Ok(2));
        assert_eq!(eval("\t42 "), Ok(42));
        assert_eq!(eval("007"), Ok(7));
    }

    #[test]
    fn division_semantics() {
        assert_eq!(eval("-7 / 2"), Ok(-3));
        assert_eq!(eval("-7 % 3"), Ok(-1));
        assert_eq!(eval("7 % -3"), Ok(1));
        assert_eq!(eval("1 / 0"), Err(CalcError::DivisionByZero));
        assert_eq!(eval("5 % (2 - 2)"), Err(CalcError::DivisionByZero));
    }

    #[test]
    fn unary_minus() {
        assert_eq!(eval("--5"), Ok(5));
        assert_eq!(eval("2 * -3"), Ok(-6));
        assert_eq!(eval("1 - -2"), Ok(3));
        assert_eq!(eval("-(2 + 3)"), Ok(-5));
        assert_eq!(eval("-2 * 3"), Ok(-6));
        assert_eq!(eval("- - - 1"), Ok(-1));
    }

    #[test]
    fn overflow() {
        assert_eq!(eval("9223372036854775807"), Ok(i64::MAX));
        assert_eq!(eval("9223372036854775808"), Err(CalcError::Overflow));
        assert_eq!(eval("-9223372036854775808"), Err(CalcError::Overflow));
        assert_eq!(eval("-9223372036854775807 - 1"), Ok(i64::MIN));
        assert_eq!(eval("9223372036854775807 + 1"), Err(CalcError::Overflow));
        assert_eq!(
            eval("-(-9223372036854775807 - 1)"),
            Err(CalcError::Overflow)
        );
        assert_eq!(
            eval("(-9223372036854775807 - 1) / -1"),
            Err(CalcError::Overflow)
        );
        assert_eq!(eval("(-9223372036854775807 - 1) % -1"), Ok(0));
        assert_eq!(eval("4611686018427387904 * 2"), Err(CalcError::Overflow));
    }

    #[test]
    fn syntax_errors() {
        for bad in [
            "1 +", "abc", "()", "1 2", "+1", "(1 + 2", "1 + 2)", ")(", "1 -", "-", "(", "1 ** 2",
            "1\r", "2(3)", "(1)(2)",
        ] {
            assert_eq!(eval(bad), Err(CalcError::Syntax), "{bad:?}");
        }
    }

    #[test]
    fn deep_nesting_does_not_recurse() {
        let depth = 1_000_000;
        let expr = format!("{}1{}", "(".repeat(depth), ")".repeat(depth));
        assert_eq!(eval(&expr), Ok(1));
        let negs = format!("{}7", "-".repeat(depth));
        assert_eq!(eval(&negs), Ok(7));
    }
}

//! `app lru`: an LRU cache simulator (see SPEC.md, section `lru`).
//!
//! The cache is a hash map from key to slot index plus an intrusive doubly
//! linked list threaded through a slot arena (`Vec<Node>`). Indices instead of
//! pointers keep it safe, and freed slots are recycled, so every command runs
//! in O(1) expected time with no per-command allocation once the arena is warm.

use std::collections::HashMap;
use std::io::{self, BufRead, BufWriter, Write};

/// Sentinel index meaning "no node".
const NIL: usize = usize::MAX;

/// Largest capacity the spec allows.
const MAX_CAPACITY: usize = 1_000_000;

/// Entry point for `app lru`: reads standard input, writes standard output.
pub fn run() -> io::Result<()> {
    let stdin = io::stdin().lock();
    let stdout = io::stdout().lock();
    simulate(
        io::BufReader::with_capacity(1 << 16, stdin),
        BufWriter::with_capacity(1 << 16, stdout),
    )
}

/// Runs the simulator: the first line of `input` is the capacity, every
/// later line a command whose output (if any) is written to `output`.
fn simulate(mut input: impl BufRead, mut output: impl Write) -> io::Result<()> {
    let mut line = Vec::new();
    if input.read_until(b'\n', &mut line)? == 0 {
        return Ok(());
    }
    let capacity = parse_capacity(&line)?;
    let mut cache = LruCache::new(capacity);

    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            break;
        }
        let Some(command) = Command::parse(strip_line_ending(&line)) else {
            // Blank or malformed lines produce no output.
            continue;
        };
        match command {
            Command::Set(key, value) => cache.set(key, value),
            Command::Get(key) => match cache.get(key) {
                Some(value) => {
                    output.write_all(value)?;
                    output.write_all(b"\n")?;
                }
                None => output.write_all(b"NULL\n")?,
            },
            Command::Del(key) => {
                output.write_all(if cache.remove(key) { b"1\n" } else { b"0\n" })?;
            }
            Command::Size => writeln!(output, "{}", cache.len())?,
        }
    }
    output.flush()
}

fn parse_capacity(line: &[u8]) -> io::Result<usize> {
    std::str::from_utf8(line)
        .ok()
        .and_then(|text| text.trim().parse::<usize>().ok())
        .filter(|capacity| (1..=MAX_CAPACITY).contains(capacity))
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("capacity must be an integer in 1..={MAX_CAPACITY}"),
            )
        })
}

/// Strips a trailing `\n` (and a `\r` before it, for tolerance of CRLF input).
fn strip_line_ending(line: &[u8]) -> &[u8] {
    let line = line.strip_suffix(b"\n").unwrap_or(line);
    line.strip_suffix(b"\r").unwrap_or(line)
}

/// One parsed input command, borrowing its operands from the input line.
#[derive(Debug, PartialEq, Eq)]
enum Command<'a> {
    Set(&'a [u8], &'a [u8]),
    Get(&'a [u8]),
    Del(&'a [u8]),
    Size,
}

impl<'a> Command<'a> {
    /// Parses a line (without its terminator); `None` if it is not a command.
    fn parse(line: &'a [u8]) -> Option<Self> {
        let mut tokens = line.split(|&b| b == b' ').filter(|t| !t.is_empty());
        let command = match (tokens.next()?, tokens.next(), tokens.next()) {
            (b"SET", Some(key), Some(value)) => Command::Set(key, value),
            (b"GET", Some(key), None) => Command::Get(key),
            (b"DEL", Some(key), None) => Command::Del(key),
            (b"SIZE", None, None) => Command::Size,
            _ => return None,
        };
        tokens.next().is_none().then_some(command)
    }
}

/// A slot in the arena: an entry plus its links in the recency list.
#[derive(Debug)]
struct Node {
    key: Box<[u8]>,
    value: Vec<u8>,
    /// Neighbour towards the most recently used end.
    prev: usize,
    /// Neighbour towards the least recently used end.
    next: usize,
}

/// A fixed-capacity map that evicts its least recently used key on overflow.
#[derive(Debug)]
struct LruCache {
    capacity: usize,
    map: HashMap<Box<[u8]>, usize>,
    nodes: Vec<Node>,
    /// Indices of unused slots in `nodes`, ready for reuse.
    free: Vec<usize>,
    /// Most recently used node.
    head: usize,
    /// Least recently used node.
    tail: usize,
}

impl LruCache {
    fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "LRU capacity must be positive");
        Self {
            capacity,
            map: HashMap::new(),
            nodes: Vec::new(),
            free: Vec::new(),
            head: NIL,
            tail: NIL,
        }
    }

    fn len(&self) -> usize {
        self.map.len()
    }

    /// Returns the value for `key`, marking it most recently used.
    fn get(&mut self, key: &[u8]) -> Option<&[u8]> {
        let index = *self.map.get(key)?;
        self.move_to_front(index);
        Some(&self.nodes[index].value)
    }

    /// Inserts or overwrites `key`, marking it most recently used and evicting
    /// the least recently used key if the cache would exceed its capacity.
    fn set(&mut self, key: &[u8], value: &[u8]) {
        if let Some(&index) = self.map.get(key) {
            let node = &mut self.nodes[index];
            node.value.clear();
            node.value.extend_from_slice(value);
            self.move_to_front(index);
            return;
        }

        // Evicting before inserting is equivalent to the spec's
        // insert-then-evict: the new key is never the least recently used.
        if self.map.len() == self.capacity {
            self.evict_lru();
        }

        let key: Box<[u8]> = key.into();
        let node = Node {
            key: key.clone(),
            value: value.to_vec(),
            prev: NIL,
            next: NIL,
        };
        let index = if let Some(index) = self.free.pop() {
            self.nodes[index] = node;
            index
        } else {
            self.nodes.push(node);
            self.nodes.len() - 1
        };
        self.map.insert(key, index);
        self.push_front(index);
    }

    /// Removes `key`, returning whether it was present.
    fn remove(&mut self, key: &[u8]) -> bool {
        match self.map.remove(key) {
            Some(index) => {
                self.release(index);
                true
            }
            None => false,
        }
    }

    fn evict_lru(&mut self) {
        let index = self.tail;
        debug_assert_ne!(index, NIL, "evicting from an empty cache");
        self.map.remove(&self.nodes[index].key);
        self.release(index);
    }

    /// Unlinks a slot whose map entry is already gone and recycles it.
    fn release(&mut self, index: usize) {
        self.unlink(index);
        let node = &mut self.nodes[index];
        node.key = Box::default();
        node.value = Vec::new();
        self.free.push(index);
    }

    fn move_to_front(&mut self, index: usize) {
        if self.head != index {
            self.unlink(index);
            self.push_front(index);
        }
    }

    fn unlink(&mut self, index: usize) {
        let Node { prev, next, .. } = self.nodes[index];
        match prev {
            NIL => self.head = next,
            prev => self.nodes[prev].next = next,
        }
        match next {
            NIL => self.tail = prev,
            next => self.nodes[next].prev = prev,
        }
        let node = &mut self.nodes[index];
        node.prev = NIL;
        node.next = NIL;
    }

    fn push_front(&mut self, index: usize) {
        let old_head = self.head;
        let node = &mut self.nodes[index];
        node.prev = NIL;
        node.next = old_head;
        match old_head {
            NIL => self.tail = index,
            old_head => self.nodes[old_head].prev = index,
        }
        self.head = index;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn run_str(input: &str) -> String {
        let mut out = Vec::new();
        simulate(input.as_bytes(), &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        let input = "2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n";
        assert_eq!(run_str(input), "1\nNULL\n2\n");
    }

    #[test]
    fn overwrite_refreshes_recency() {
        let input = "2\nSET a 1\nSET b 2\nSET a 9\nSET c 3\nGET a\nGET b\nGET c";
        assert_eq!(run_str(input), "9\nNULL\n3\n");
    }

    #[test]
    fn delete_and_size() {
        let input = "3\nSET x 1\nDEL x\nDEL x\nSIZE\nGET x\n";
        assert_eq!(run_str(input), "1\n0\n0\nNULL\n");
    }

    #[test]
    fn capacity_one() {
        let input = "1\nSET a 1\nSET b 2\nGET a\nGET b\nSIZE\n";
        assert_eq!(run_str(input), "NULL\n2\n1\n");
    }

    #[test]
    fn freed_slots_are_reused_consistently() {
        let input = "2\nSET a 1\nSET b 2\nDEL a\nSET c 3\nSET d 4\nGET b\nGET c\nGET d\nSIZE\n";
        assert_eq!(run_str(input), "1\nNULL\n3\n4\n2\n");
    }

    #[test]
    fn get_refreshes_recency() {
        let input = "2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET a\nGET b\n";
        assert_eq!(run_str(input), "1\n1\nNULL\n");
    }

    #[test]
    fn empty_input_prints_nothing() {
        assert_eq!(run_str(""), "");
        assert_eq!(run_str("5\n"), "");
    }

    #[test]
    fn rejects_invalid_capacity() {
        let mut out = Vec::new();
        assert!(simulate("0\n".as_bytes(), &mut out).is_err());
        assert!(simulate("abc\n".as_bytes(), &mut out).is_err());
    }

    #[test]
    fn parses_commands() {
        assert_eq!(Command::parse(b"SET k v"), Some(Command::Set(b"k", b"v")));
        assert_eq!(Command::parse(b"GET k"), Some(Command::Get(b"k")));
        assert_eq!(Command::parse(b"DEL k"), Some(Command::Del(b"k")));
        assert_eq!(Command::parse(b"SIZE"), Some(Command::Size));
        assert_eq!(Command::parse(b""), None);
        assert_eq!(Command::parse(b"GET"), None);
        assert_eq!(Command::parse(b"SET k"), None);
        assert_eq!(Command::parse(b"NOPE k"), None);
    }
}

//! `app`: a suite of independent subcommands that read stdin and write stdout.
//!
//! Each subcommand lives in its own module and exposes a single entry point,
//! `run() -> io::Result<()>`, which owns its I/O end to end.

mod calc;
mod lru;
mod wordfreq;

use std::env;
use std::io;
use std::process::ExitCode;

type EntryPoint = fn() -> io::Result<()>;

const SUBCOMMANDS: &[(&str, EntryPoint)] = &[
    ("wordfreq", wordfreq::run),
    ("lru", lru::run),
    ("calc", calc::run),
];

fn usage() -> String {
    let names: Vec<&str> = SUBCOMMANDS.iter().map(|&(name, _)| name).collect();
    format!("usage: app <{}>", names.join("|"))
}

fn main() -> ExitCode {
    let Some(command) = env::args().nth(1) else {
        eprintln!("{}", usage());
        return ExitCode::from(2);
    };

    let Some(&(_, run)) = SUBCOMMANDS.iter().find(|&&(name, _)| name == command) else {
        eprintln!("app: unknown subcommand '{command}'\n{}", usage());
        return ExitCode::from(2);
    };

    match run() {
        Ok(()) => ExitCode::SUCCESS,
        // A closed stdout (e.g. `app wordfreq | head`) is not a failure.
        Err(err) if err.kind() == io::ErrorKind::BrokenPipe => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("app {command}: {err}");
            ExitCode::FAILURE
        }
    }
}

//! `app wordfreq`: word frequencies (see SPEC.md, section `wordfreq`).
//!
//! A word is a maximal run of ASCII letters, folded to lowercase; every other
//! byte is a separator. The input is lowercased in place once, so words can be
//! counted as borrowed slices of the input buffer without per-word allocation.

use std::cmp::Ordering;
use std::collections::HashMap;
use std::hash::{BuildHasherDefault, Hasher};
use std::io::{self, BufWriter, Read, Write};

/// How many of the most frequent words to print.
const TOP_N: usize = 10;

/// Entry point for `app wordfreq`: reads standard input, writes standard output.
pub fn run() -> io::Result<()> {
    let mut input = Vec::new();
    io::stdin().lock().read_to_end(&mut input)?;
    input.make_ascii_lowercase();

    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    for (word, count) in top_words(&input, TOP_N) {
        write!(out, "{count} ")?;
        out.write_all(word)?;
        out.write_all(b"\n")?;
    }
    out.flush()
}

/// Splits `text` into maximal runs of ASCII letters.
///
/// Letters are returned as they appear; callers wanting case-insensitive
/// words must fold `text` beforehand.
fn words(text: &[u8]) -> impl Iterator<Item = &[u8]> {
    text.split(|byte| !byte.is_ascii_alphabetic())
        .filter(|word| !word.is_empty())
}

/// Returns the `n` most frequent words of `text` with their counts, ordered by
/// count descending, then by word ascending (byte order).
///
/// Words are compared byte for byte, so `text` should already be case-folded.
fn top_words(text: &[u8], n: usize) -> Vec<(&[u8], u64)> {
    let mut counts: HashMap<&[u8], u64, BuildFnv> = HashMap::default();
    for word in words(text) {
        *counts.entry(word).or_insert(0) += 1;
    }

    let mut ranked: Vec<(&[u8], u64)> = counts.into_iter().collect();
    // Order by frequency, most frequent first; break ties alphabetically.
    let rank = |a: &(&[u8], u64), b: &(&[u8], u64)| -> Ordering {
        b.1.cmp(&a.1).then_with(|| a.0.cmp(b.0))
    };
    if ranked.len() > n {
        if n == 0 {
            return Vec::new();
        }
        // Partition so the first `n` entries are the top `n`, in O(len).
        ranked.select_nth_unstable_by(n - 1, rank);
        ranked.truncate(n);
    }
    ranked.sort_unstable_by(rank);
    ranked
}

/// Builds [`FnvHasher`]s for the word-count map.
type BuildFnv = BuildHasherDefault<FnvHasher>;

/// 64-bit FNV-1a: much faster than the default `SipHash` for the short keys
/// this module hashes. It is not DoS-resistant, which is acceptable for a
/// one-shot command-line tool processing its own input.
struct FnvHasher(u64);

impl Default for FnvHasher {
    fn default() -> Self {
        const OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
        Self(OFFSET_BASIS)
    }
}

impl Hasher for FnvHasher {
    fn write(&mut self, bytes: &[u8]) {
        const PRIME: u64 = 0x0000_0100_0000_01b3;
        for &byte in bytes {
            self.0 ^= u64::from(byte);
            self.0 = self.0.wrapping_mul(PRIME);
        }
    }

    fn finish(&self) -> u64 {
        self.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn top(text: &str) -> Vec<(String, u64)> {
        let mut folded = text.as_bytes().to_vec();
        folded.make_ascii_lowercase();
        top_words(&folded, TOP_N)
            .into_iter()
            .map(|(word, count)| (String::from_utf8(word.to_vec()).unwrap(), count))
            .collect()
    }

    fn pairs(expected: &[(&str, u64)]) -> Vec<(String, u64)> {
        expected.iter().map(|&(w, c)| (w.to_owned(), c)).collect()
    }

    #[test]
    fn spec_example() {
        assert_eq!(
            top("The cat and the hat."),
            pairs(&[("the", 2), ("and", 1), ("cat", 1), ("hat", 1)])
        );
    }

    #[test]
    fn no_words() {
        assert!(top("").is_empty());
        assert!(top("123 _ ' !? \n\t").is_empty());
    }

    #[test]
    fn non_letters_separate_words() {
        assert_eq!(
            top("don't stop_me 4now, now-NOW"),
            pairs(&[("now", 3), ("don", 1), ("me", 1), ("stop", 1), ("t", 1)])
        );
    }

    #[test]
    fn non_ascii_bytes_are_separators() {
        let mut input = b"caf\xc3\xa9 caf\xff\xfeX".to_vec();
        input.make_ascii_lowercase();
        let result = top_words(&input, TOP_N);
        assert_eq!(result, vec![(&b"caf"[..], 2), (&b"x"[..], 1)]);
    }

    #[test]
    fn keeps_only_top_ten_with_ties_by_word() {
        let result = top("zeta eta theta iota kappa lambda mu nu xi omicron pi rho alpha beta alpha");
        let words: Vec<&str> = result.iter().map(|(w, _)| w.as_str()).collect();
        assert_eq!(
            words,
            ["alpha", "beta", "eta", "iota", "kappa", "lambda", "mu", "nu", "omicron", "pi"]
        );
        assert_eq!(result[0].1, 2);
    }

    #[test]
    fn zero_limit_returns_nothing() {
        assert!(top_words(b"a b c", 0).is_empty());
    }
}
